import { App } from "..";
export class Controller {
    app: App;
    pos = [0, 0]
    isDown = false
    constructor(app: App) {
        this.app = app;
    }
    public init() {
        this.appendEvent();
    }
    public appendEvent() {
        this.app.renderer.canvas.addEventListener('drag', (e: MouseEvent) => {
            // console.log('click', e);
        }, false);
        this.app.renderer.canvas.addEventListener('click', (e: MouseEvent) => {
            // console.log('click', e);
        }, false);
        this.app.renderer.canvas.addEventListener('dblclick', (e: MouseEvent) => {
            // console.log('d-click', e);
        }, false);
        this.app.renderer.canvas.addEventListener('drag', (e: MouseEvent) => {
            // console.log('drag', e);
        }, true);
        this.app.renderer.canvas.addEventListener('mouseup', (e: MouseEvent) => {
            // console.log('mouse up', e);
        }, false);
        this.app.renderer.canvas.addEventListener('mousedown', (e: MouseEvent) => {
            this.isDown = true;
            this.pos[0] = e.offsetX;
            this.pos[1] = e.offsetY;
            // this.app.renderer.camera.translateX(0.25)
            // this.app.renderer.cameraController.translateX();
            // this.app.renderer.cameraController.rotateZ();
            // console.log('pointer down', e);
        }, false);
        this.app.renderer.canvas.addEventListener('mouseup', (e: MouseEvent) => {
            // console.log('pointer up', e);
            this.isDown = false;
        }, false);
        this.app.renderer.canvas.addEventListener('mousemove', (e: MouseEvent) => {
            if (this.isDown) {
                // console.log('move dragging')
                const xOff = this.pos[0] - e.offsetX;
                const yOff = this.pos[1] - e.offsetY;

                this.app.renderer.cameraController.arcRotation(xOff, yOff)
                this.pos[0] = e.offsetX;
                this.pos[1] = e.offsetY;

            } else {
                // console.log('move')
            }

            // console.log('mousemove', e);
        }, false);
        this.app.renderer.canvas.addEventListener('wheel', (e:  WheelEvent) => {
            // console.log('wheel', e.deltaY);
            this.app.renderer.cameraController.zoomWheel(e.deltaY)
        }, false);
    }
}