import { Controller } from './Controller';
import { Renderer } from './Renderer';
import { Scene } from './Scene';

// https://www.youtube.com/playlist?list=PLn3eTxaOtL2Ns3wkxdyS3CiqkJuwQdZzn
// https://www.youtube.com/playlist?list=PL_UrKDEhALdKh0118flOjuAnVIGKFUJXN

// https://webgpufundamentals.org/
// https://webgpu.github.io/webgpu-samples/

// https://antongerdelan.net/opengl/raycasting.html

export class App {
    public divHost: HTMLElement;

    public controller: Controller;
    public renderer: Renderer;
    public scene: Scene;

    constructor(id: string) {
        this.divHost = document.getElementById(id) as HTMLDivElement;

        this.renderer = new Renderer(this)
        this.controller = new Controller(this);
        this.scene = new Scene(this);

        this.init();
    }
    public async init() {
        this.controller.init();
        await this.renderer.init();
        await this.scene.init();
    };
    public destroy() {
        this.renderer.destroy();

        if (this.divHost) {
            try {
                while (this.divHost.firstChild) {
                    this.divHost.removeChild(this.divHost.firstChild);
                }
            } catch (error) {
                console.error('Error in destroy method:', error);
            }
        } else {
            console.warn('divHost is undefined in destroy method');
        }
    }
}


export class Solution {
    public app: App
    constructor(id: string) {
        this.app = new App(id)
    }
    public destroy() {
        this.app.destroy();
    }
}