import { loadWGSL } from '../../lib';
import { mat4, vec3 } from "gl-matrix";

import { Scene } from '../../Scene';
import { ObjectBase } from '../../Geometry/Base';

import shaderPath from './shaders.wgsl';

export class TriMeshUniform extends ObjectBase {


    buffer: GPUBuffer
    bufferLayout: GPUVertexBufferLayout
    uniformBuffer;

    pipeline;
    bindGroup;

    t = 0.0;

    isRenderable= false;

    constructor(scene: Scene) {
        super(scene)

        // x y r g b
        const vertices: Float32Array = new Float32Array(
            [
                0.0,  0.0,  1.5, 1.0, 0.0, 0.0,
                0.0, -1.5, -1.5, 0.0, 1.0, 0.0,
                0.0,  1.5, -1.5, 0.0, 0.0, 1.0
            ]
        );

        const usage: GPUBufferUsageFlags = GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST;
        //VERTEX: the buffer can be used as a vertex buffer
        //COPY_DST: data can be copied to the buffer

        const descriptor: GPUBufferDescriptor = {
            size: vertices.byteLength,
            usage: usage,
            mappedAtCreation: true // similar to HOST_VISIBLE, allows buffer to be written by the CPU
        };

        this.buffer = this.webGPU.device.createBuffer(descriptor);

        //Buffer has been created, now load in the vertices
        new Float32Array(this.buffer.getMappedRange()).set(vertices);
        this.buffer.unmap();

        //now define the buffer layout
        this.bufferLayout = {
            arrayStride: 24,
            // @ts-ignore
            attributes: [
                {
                    shaderLocation: 0,
                    format: "float32x3",
                    offset: 0
                },
                {
                    shaderLocation: 1,
                    format: "float32x3",
                    offset: 12
                }
            ]
        }
        this.initPipeline();
    }
    async initPipeline () {

        this.uniformBuffer = this.webGPU.device.createBuffer({
            size: 64 * 3,
            usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST
        });

        // const bindGroupLayout = this.webGPU.device.createBindGroupLayout({
        //     entries: [],
        // });

        const bindGroupLayout = this.webGPU.device.createBindGroupLayout({
            entries: [
                {
                    binding: 0,
                    visibility: GPUShaderStage.VERTEX,
                    buffer: {}
                }
            ]

        });
    
        // this.bindGroup = this.webGPU.device.createBindGroup({
        //     layout: bindGroupLayout,
        //     entries: []
        // });

        this.bindGroup = this.webGPU.device.createBindGroup({
            layout: bindGroupLayout,
            entries: [
                {
                    binding: 0,
                    resource: {
                        buffer: this.uniformBuffer
                    }
                }
            ]
        });
        
        const pipelineLayout = this.webGPU.device.createPipelineLayout({
            bindGroupLayouts: [bindGroupLayout]
        });
    
        const shader = await loadWGSL(shaderPath);

        this.pipeline = this.webGPU.device.createRenderPipeline({
            vertex : {
                module : this.webGPU.device.createShaderModule({
                    // @ts-ignore
                    code : shader
                }),
                entryPoint : "vs_main",
                buffers: [this.bufferLayout,]
            },
    
            fragment : {
                module : this.webGPU.device.createShaderModule({
                    // @ts-ignore
                    code : shader
                }),
                entryPoint : "fs_main",
                targets : [{
                    format : this.webGPU.format
                }]
            },
    
            primitive : {
                topology : "triangle-list"
            },
    
            layout: pipelineLayout
        });
        this.isRenderable = true;
    }
    render() {
        if (!this.isRenderable) { return; }

        this.t += 0.01;
        if (this.t > 2.0 * Math.PI) {
            // this.t -= 2.0 * Math.PI;
        }
        

        //make transforms
        let projection = mat4.create();
        // load perspective projection into the projection matrix,
        // Field of view = 45 degrees (pi/4)
        // Aspect ratio = 800/600
        // near = 0.1, far = 10 
        const fovy = Math.PI/4;
        const aspect = this.webGPU.renderer.canvas.width/this.webGPU.renderer.canvas.height
        const near = 0.1
        const far = 10
        mat4.perspective(projection, fovy, aspect, near,far );


        let view = mat4.create();
        // console.log(view)
        //load lookat matrix into the view matrix,
        //looking from [-2, 0, 2]
        //looking at [0, 0, 0]
        //up vector is [0, 0, 1]
        const eye = vec3.fromValues(-2, 0, 2);
        const center = vec3.fromValues(0, 0, 0);
        const up = vec3.fromValues(0, 0, 1)
        mat4.lookAt(view, eye, center, up);



        
        const model = mat4.create();
        //Store, in the model matrix, the model matrix after rotating it by t radians around the z axis.
        //(yeah, I know, kinda weird.)

        // mat4.rotate(model, model, this.t, [0,1,0]);
        mat4.translate(model, model, [Math.sin(this.t ),0,0]);

        let hasCamera = true;
        if (hasCamera){
            projection = this.webGPU.renderer.cameraController.camera.projectionMatrix;
            view = this.webGPU.renderer.cameraController.camera.viewMatrix;
        } 
        

        this.webGPU.device.queue.writeBuffer(this.uniformBuffer, 0, model as ArrayBuffer); 
        this.webGPU.device.queue.writeBuffer(this.uniformBuffer, 64, view as ArrayBuffer); 
        this.webGPU.device.queue.writeBuffer(this.uniformBuffer, 128, projection as ArrayBuffer); 


        //command encoder: records draw commands for submission
        const commandEncoder : GPUCommandEncoder = this.webGPU.device.createCommandEncoder();
        //texture view: image view to the color buffer in this case
        const textureView : GPUTextureView = this.webGPU.ctx.getCurrentTexture().createView();
        //renderpass: holds draw commands, allocated from command encoder
        const renderpass : GPURenderPassEncoder = commandEncoder.beginRenderPass({
            // @ts-ignore
            colorAttachments: [{
                view: textureView,
                clearValue: {r: 0.0, g: 0.0, b: 0.0, a: 1.0},
                loadOp: "clear",
                storeOp: "store"
            }]
        });
        // renderpass.setPipeline(this.pipeline);
        // renderpass.setVertexBuffer(0, this.buffer);
        // renderpass.setBindGroup(0, this.bindGroup)
        // renderpass.draw(3, 1, 0, 0);
        // renderpass.end();
    
        // this.webGPU.device.queue.submit([commandEncoder.finish()]);



        renderpass.setPipeline(this.pipeline);
        renderpass.setVertexBuffer(0, this.buffer);
        renderpass.setBindGroup(0, this.bindGroup);
        renderpass.draw(3, 1, 0, 0);
        renderpass.end();
    
        this.webGPU.device.queue.submit([commandEncoder.finish()]);
    }
}